result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/canon.mjs", "content": "// Canonical JSON writer.
//
// Canonical form guarantees:
//   - object keys are sorted lexicographically (by UTF-16 code unit) at EVERY depth
//   - no whitespace between tokens
//   - deterministic across runs and machines (no reliance on insertion order)
//
// Note on JS object key ordering quirks: for integer-like keys ("9", "10"),
// JS engines enumerate them FIRST in ascending NUMERIC order regardless of
// insertion order ("10" before "9" never happens in Object.keys()). Our
// explicit Array.prototype.sort() below restores the intended LEXICOGRAPHIC
// order ("10" < "9"), so canonical output does not depend on engine quirks.
export function canonicalJson(value) {
  return write(value);
}
function write(v) {
  if (v === null || typeof v === "number" || typeof v === "boolean") return JSON.stringify(v);
  if (typeof v === "string") return JSON.stringify(v);
  if (Array.isArray(v)) return "[" + v.map(write).join(",") + "]";
  const keys = Object.keys(v).sort();
  return "{" + keys.map(function (k) { return JSON.stringify(k) + ":" + write(v[k]); }).join(",") + "}";
}
