result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/canon.test.mjs", "content": "// Golden-file tests for the canonical-JSON writer.
//
// Layout:
//   fixtures/*.input.json  -- raw inputs (parsed with JSON.parse)
//   fixtures/*.golden.txt  -- expected canonical output (byte-exact)
//
// Regenerate all goldens after an INTENTIONAL format change:
//   UPDATE_GOLDEN=1 node --test canon.test.mjs
//
// Notes pinned by dedicated tests below:
//   - JSON.stringify(-0) === "0": canonical JSON collapses -0 and 0 (lossy,
//     but stable). The -0 fixture therefore round-trips to plain 0.
//   - JSON.stringify(1e21) === "1e+21": numbers >= 1e21 switch to exponent
//     notation; canonical output pins that exact spelling.

import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { canonicalJson } from './canon.mjs';

const here = path.dirname(fileURLToPath(import.meta.url));
const fixturesDir = path.join(here, 'fixtures');
const inputFiles = fs.readdirSync(fixturesDir)
  .filter((f) => f.endsWith('.input.json'))
  .sort();

const goldenPathFor = (inputFile) =>
  path.join(fixturesDir, inputFile.replace(/\.input\.json$/, '.golden.txt'));

// Minimal dependency-free deep equality.
// Uses === (not Object.is) on purpose: 0 and -0 compare equal, matching the
// writer's documented collapse of -0 into 0.
function deepEqual(a, b) {
  if (a === b) return true;
  if (typeof a !== typeof b) return false;
  if (Array.isArray(a) && Array.isArray(b)) {
    if (a.length !== b.length) return false;
    return a.every((x, i) => deepEqual(x, b[i]));
  }
  if (a && b && typeof a === 'object') {
    const ka = Object.keys(a), kb = Object.keys(b);
    if (ka.length !== kb.length) return false;
    return ka.every((k) => deepEqual(a[k], b[k]));
  }
  // NaN case: NaN !== NaN but both being NaN counts as equal here.
  return Number.isNaN(a) && Number.isNaN(b);
}

// Small diff helper worth keeping: shows the first byte where two strings
// diverge plus surrounding context, so golden failures are readable.
export function firstDiff(got, want) {
  const n = Math.max(got.length, want.length);
  for (let i = 0; i < n; i++) {
    if (got[i] !== want[i]) {
      const ctx = (s) => s.slice(Math.max(0, i - 20), i + 20);
      return `first difference at index ${i}:\n` +
        `  got : ...${JSON.stringify(ctx(got))}...\n` +
        `  want: ...${JSON.stringify(ctx(want))}...`;
    }
  }
  return 'strings are equal';
}

for (const file of inputFiles) {
  const name = file.replace(/\.input\.json$/, '');

  test(`golden [byte-exact]: ${name}`, () => {
    const input = JSON.parse(fs.readFileSync(path.join(fixturesDir, file), 'utf8'));
    const out = canonicalJson(input);
    const gp = goldenPathFor(file);

    if (process.env.UPDATE_GOLDEN) {
      fs.writeFileSync(gp, out);
      return;
    }

    assert.ok(fs.existsSync(gp), `missing golden file: ${gp}`);
    // Byte-exact: compare as buffers, not merely structurally-equal strings.
    const got = Buffer.from(out, 'utf8');
    const want = fs.readFileSync(gp);
    assert.ok(
      Buffer.compare(got, want) === 0,
      `canonical output does not match golden for ${name}\n${firstDiff(out, want.toString('utf8'))}`
    );
  });

  test(`property / idempotence + round-trip: ${name}`, () => {
    const input = JSON.parse(fs.readFileSync(path.join(fixturesDir, file), 'utf8'));
    const out = canonicalJson(input);

    // Idempotence: re-canonicalizing the parsed output is a fixed point.
    assert.equal(
      canonicalJson(JSON.parse(out)),
      out,
      `canonicalJson is not idempotent for ${name}`
    );

    // Round-trip: parsing the canonical output yields a value deep-equal to
    // the original parsed input (modulo documented -0 -> 0 collapse).
    assert.ok(
      deepEqual(JSON.parse(out), input),
      `JSON.parse(canonicalJson(x)) not deep-equal to x for ${name}`
    );
  });
}

// ---------------------------------------------------------------------------
// Cross-fixture pair: 01-nested-shuffled and 02-nested-shuffled-twin encode
// the SAME logical value with different key insertion orders at every level.
// Canonicalization MUST erase that difference entirely.
// ---------------------------------------------------------------------------
test('cross-fixture: key-order twins produce identical canonical bytes', () => {
  const a = path.join(fixturesDir, '01-nested-shuffled.input.json');
  const b = path.join(fixturesDir, '02-nested-shuffled-twin.input.json');
  const outA = canonicalJson(JSON.parse(fs.readFileSync(a, 'utf8')));
  const outB = canonicalJson(JSON.parse(fs.readFileSync(b, 'utf8')));
  assert.equal(outA, outB, 'key order must not leak into canonical output');
});

test('pinned: -0 canonicalizes to "0" (JSON.stringify semantics)', () => {
  // JSON.stringify(-0) === "0": the sign of negative zero is not representable
  // in the output. This is intentional and pinned: canonical form is stable,
  // and -0 and 0 cannot be distinguished after a round-trip.
  assert.equal(JSON.stringify(-0), '0');
  assert.equal(canonicalJson(-0), '0');
  assert.equal(canonicalJson([-0, 0]), '[0,0]');
  // Consequence for round-tripping: parse(output) sees plain 0.
  assert.equal(JSON.parse(canonicalJson({ v: -0 })).v, 0);
});

test('pinned: 1e21 canonicalizes to "1e+21" (exponent notation)', () => {
  // JSON.stringify switches to exponent notation at >= 1e21 and spells it
  // with an explicit "+" in the exponent. Pinned so any JS/engine change
  // in number formatting surfaces as a test failure, not a silent golden drift.
  assert.equal(JSON.stringify(1e21), '1e+21');
  assert.equal(canonicalJson(1e21), '1e+21');
});

test('numeric-like keys: sort() overrides integer-key enumeration order', () => {
  // Quirk: Object.keys({"10":..,"9":..,"2":..}) enumerates integer-like keys
  // FIRST in ascending NUMERIC order ("2","9","10"), regardless of insertion
  // order — unlike non-integer keys, which follow insertion order.
  const obj = { '10': 'ten', '9': 'nine', '2': 'two', alpha: 'string key' };
  assert.deepEqual(Object.keys(obj), ['2', '9', '10', 'alpha']);
  // Our explicit .sort() restores full lexicographic intent over ALL keys:
  // "10" < "2" < "9" < "alpha" by UTF-16 code units.
  assert.equal(
    canonicalJson(obj),
    '{"10":"ten","2":"two","9":"nine","alpha":"string key"}'
  );
});
"})
